$work=dirname(__DIR__,2).'/work';$name='readyfinance_importtest_'.gmdate('YmdHis');$db=new PDO('mysql:host=127.0.0.1','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$db->exec('USE `'.$name.'`');foreach(glob(dirname(__DIR__).'/database/*.sql') as $file)$db->exec(file_get_contents($file));$migration=require dirname(__DIR__).'/database/003_storage.php';$migration($db);
$config=['dsn'=>'mysql:host=127.0.0.1;dbname='.$name.';charset=utf8mb4','user'=>'root','password'=>'','storage'=>$work.'/import-test-storage','installation_uuid'=>Core::uuid(),'base_path'=>''];file_put_contents($work.'/import-test-config.php','<?php return '.var_export($config,true).';');putenv('RPF_CONFIG='.$work.'/import-test-config.php');$c=new Core();$f=new Finance($c);$owner=$f->setup(['name'=>'Import test','household'=>'Isolated imports','email'=>'imports@example.invalid','password'=>bin2hex(random_bytes(16))]);$h=$owner['household_id'];$u=$owner['user_id'];$accounts=[];foreach(['Main bank','Second bank'] as $n)$accounts[]=$f->create($h,$u,'account',['name'=>$n,'type'=>'bank','opening'=>'1000','opening_date'=>'2025-01-01']);$a=$accounts[0]['uuid'];$other=$accounts[1]['uuid'];$cats=[];foreach($c->all('SELECT uuid,name FROM categories WHERE household_id=?',[$h]) as $cat)$cats[$cat['name']]=$cat['uuid'];$service=new ImportService($c);
