$again=uploadCsv($service,$h,$u,$a,$work,$csv,'overlap.csv');test(count(array_filter($again['rows'],fn($r)=>$r['duplicate_id']))===3,'Overlapping file rows detected');$r=$service->commit($h,$u,$again['batch']['uuid'],array_map(fn($r)=>['id'=>$r['id'],'type'=>'skip'],$again['rows']),true);test($r['result']['duplicates']===3&&$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn()==$before,'Duplicate uploads have one economic effect');
$existing=(new Accounting($c))->post($h,$u,['type'=>'expense','amount'=>'25','date'=>'2025-01-05','description'=>'Already entered','account_uuid'=>$a,'category_uuid'=>$cats['Groceries']],'test:existing');$match=uploadCsv($service,$h,$u,$a,$work,"Date,Description,Debit,Credit,Balance\n05-01-2025,Bank merchant,25,,1175\n");test(count($match['rows'][0]['matches'])===1,'Existing bank entry suggested');$before=$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn();$r=$service->commit($h,$u,$match['batch']['uuid'],[['id'=>$match['rows'][0]['id'],'type'=>'match','transaction_uuid'=>$existing['uuid']]],true);test($r['result']['matched']===1&&$c->query('SELECT COUNT(*) FROM transactions')->fetchColumn()==$before,'Matching records provenance without new posting');
