$locked=uploadCsv($service,$h,$u,$a,$work,"Date,Description,Debit,Credit,Balance\n01-02-2025,Locked expense,1,,1224\n");$c->query('INSERT INTO periods(household_id,month,locked,reason) VALUES(?,?,1,?)',[$h,'2025-02','Test lock']);fails(fn()=>$service->commit($h,$u,$locked['batch']['uuid'],[['id'=>$locked['rows'][0]['id'],'type'=>'expense','category_uuid'=>$cats['Groceries']]],true),'Period locks apply to imports');
